// 1) List Remote Buckets or Objects from AWS S3, MinIO, Ceph RGW, or S3-Compatible Endpoint
app.post('/api/project/:id/storage/s3-compatible/list', async (req, res) => {
  const {
    providerType = 'MINIO', // AWS_S3 | MINIO | CEPH_RGW | S3_COMPATIBLE
    endpoint = 'https://s3.us-east-1.amazonaws.com',
    region = 'us-east-1',
    remoteBucket = '',
    prefix = '',
    accessKeyId = '',
    secretAccessKey = '',
    sessionToken = '',
    pathStyle = true,
    useSandboxDemo = false,
  } = req.body || {};

  if (useSandboxDemo) {
    const profile =
      SANDBOX_S3_COMPATIBLE_MANIFEST[providerType] ||
      SANDBOX_S3_COMPATIBLE_MANIFEST.MINIO;
    const filteredObjects = profile.objects.filter((o) =>
      prefix ? o.key.startsWith(prefix) : true
    );
    return res.json({
      ok: true,
      mode: 'SANDBOX_DEMO',
      providerType,
      endpoint: endpoint || profile.endpoint,
      region: region || profile.region,
      remoteBucket: remoteBucket || profile.bucket,
      remoteBuckets: [
        { name: profile.bucket, creationDate: new Date().toISOString() },
        { name: 'minio-edge-ai-lakehouse', creationDate: new Date().toISOString() },
        { name: 'ceph-rgw-financial-ledger', creationDate: new Date().toISOString() },
        { name: 'aws-prod-datalake-us-east-1', creationDate: new Date().toISOString() },
      ],
      objects: filteredObjects,
      message: `Connected to ${providerType} cluster (${
        remoteBucket || profile.bucket
      }) — ${filteredObjects.length} object(s) listed.`,
    });
  }

  try {
    const cleanBucket = String(remoteBucket || '').trim();
    const queryParams = cleanBucket
      ? {
          'list-type': '2',
          'max-keys': '200',
          ...(prefix ? { prefix: String(prefix).trim() } : {}),
        }
      : {};

    const signed = buildS3SignedRequest({
      method: 'GET',
      endpoint,
      region,
      bucket: cleanBucket,
      queryParams,
      accessKeyId,
      secretAccessKey,
      sessionToken,
      pathStyle: Boolean(pathStyle),
    });

    const s3Res = await gcpHttp.get(signed.url, {
      headers: signed.headers,
      responseType: 'text',
      timeout: 10000,
    });

    const xml = String(s3Res.data || '');

    if (!cleanBucket) {
      const bucketBlocks = extractXmlBlocks(xml, 'Bucket');
      const remoteBuckets = bucketBlocks.map((b) => ({
        name: extractXmlTagValue(b, 'Name'),
        creationDate: extractXmlTagValue(b, 'CreationDate') || null,
      }));
      return res.json({
        ok: true,
        mode: 'LIVE_S3_XML',
        providerType,
        endpoint,
        region,
        remoteBucket: remoteBuckets[0]?.name || '',
        remoteBuckets,
        objects: [],
        message: `Listed ${remoteBuckets.length} bucket(s) from ${endpoint}. Select a bucket to list objects.`,
      });
    }

    const contentBlocks = extractXmlBlocks(xml, 'Contents');
    const objects = contentBlocks.map((block) => ({
      key: extractXmlTagValue(block, 'Key'),
      size: Number(extractXmlTagValue(block, 'Size') || 0),
      lastModified: extractXmlTagValue(block, 'LastModified') || null,
      etag: extractXmlTagValue(block, 'ETag').replace(/"/g, ''),
      storageClass: extractXmlTagValue(block, 'StorageClass') || 'STANDARD',
    }));

    return res.json({
      ok: true,
      mode: 'LIVE_S3_XML',
      providerType,
      endpoint,
      region,
      remoteBucket: cleanBucket,
      remoteBuckets: [{ name: cleanBucket }],
      objects,
      message: `Listed ${objects.length} object(s) from ${providerType} bucket s3://${cleanBucket}.`,
    });
  } catch (err) {
    const rawXmlErr =
      typeof err.response?.data === 'string' ? err.response.data : '';
    const s3Code = extractXmlTagValue(rawXmlErr, 'Code');
    const s3Msg = extractXmlTagValue(rawXmlErr, 'Message');
    return res.status(502).json({
      error: s3Code
        ? `S3/MinIO/Ceph Error [${s3Code}]: ${s3Msg || err.message}`
        : `Failed to reach S3/MinIO/Ceph endpoint (${endpoint}): ${err.message}. Tip: Click "Load Demo MinIO / Ceph / S3 Cluster" to test the importer without an external S3 endpoint.`,
    });
  }
});

// 2) Stream-Import Selected Objects from AWS S3, MinIO, or Ceph RGW Directly into gs://:bucketName
app.post(
  '/api/project/:id/storage/buckets/:bucketName/s3-compatible/import',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    const {
      providerType = 'MINIO',
      endpoint = 'https://s3.us-east-1.amazonaws.com',
      region = 'us-east-1',
      remoteBucket = '',
      keys = [],
      targetPrefix = '',
      accessKeyId = '',
      secretAccessKey = '',
      sessionToken = '',
      pathStyle = true,
      useSandboxDemo = false,
    } = req.body || {};

    if (!Array.isArray(keys) || keys.length === 0) {
      return res
        .status(400)
        .json({ error: 'Select at least one remote S3/MinIO/Ceph object to import.' });
    }

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) {
        return res
          .status(401)
          .json({ error: 'Not authenticated with Google Cloud.' });
      }

      const cleanPrefix = String(targetPrefix || '')
        .trim()
        .replace(/^\/+/, '');
      const normalizedPrefix =
        cleanPrefix && !cleanPrefix.endsWith('/')
          ? `${cleanPrefix}/`
          : cleanPrefix;

      const importedObjects = [];
      const errors = [];

      const sandboxProfile =
        SANDBOX_S3_COMPATIBLE_MANIFEST[providerType] ||
        SANDBOX_S3_COMPATIBLE_MANIFEST.MINIO;
      const allSandboxObjects = [
        ...SANDBOX_S3_COMPATIBLE_MANIFEST.MINIO.objects,
        ...SANDBOX_S3_COMPATIBLE_MANIFEST.CEPH_RGW.objects,
        ...SANDBOX_S3_COMPATIBLE_MANIFEST.AWS_S3.objects,
      ];

      for (const key of keys.slice(0, 25)) {
        try {
          let payloadBuffer;
          let contentType = 'application/octet-stream';

          const sandboxMatch = allSandboxObjects.find((o) => o.key === key);
          if (useSandboxDemo && sandboxMatch) {
            payloadBuffer = Buffer.from(sandboxMatch.body, 'utf8');
            contentType = sandboxMatch.contentType || 'text/plain; charset=utf-8';
          } else {
            const signedGet = buildS3SignedRequest({
              method: 'GET',
              endpoint,
              region,
              bucket: remoteBucket || sandboxProfile.bucket,
              objectKey: key,
              accessKeyId,
              secretAccessKey,
              sessionToken,
              pathStyle: Boolean(pathStyle),
            });

            const s3ObjRes = await gcpHttp.get(signedGet.url, {
              headers: signedGet.headers,
              responseType: 'arraybuffer',
              timeout: 15000,
            });
            payloadBuffer = Buffer.from(s3ObjRes.data || []);
            contentType =
              s3ObjRes.headers?.['content-type'] || 'application/octet-stream';
          }

          const gcsObjectName = `${normalizedPrefix}${String(key).replace(
            /^\/+/,
            ''
          )}`;

          await gcpHttp.post(
            `https://storage.googleapis.com/upload/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/o?uploadType=media&name=${encodeURIComponent(gcsObjectName)}`,
            payloadBuffer,
            {
              headers: {
                Authorization: `Bearer ${token}`,
                'x-goog-user-project': projectId,
                'Content-Type': contentType,
              },
              timeout: 15000,
            }
          );

          // Stamp provenance metadata on the imported GCS object
          await gcpHttp
            .patch(
              `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
                bucketName
              )}/o/${encodeURIComponent(gcsObjectName)}`,
              {
                metadata: {
                  importedFromProvider: providerType,
                  sourceEndpoint: String(endpoint || ''),
                  sourceBucket: String(remoteBucket || sandboxProfile.bucket),
                  sourceObjectKey: String(key),
                  importedAt: new Date().toISOString(),
                },
              },
              {
                headers: {
                  Authorization: `Bearer ${token}`,
                  'x-goog-user-project': projectId,
                },
                timeout: 5000,
              }
            )
            .catch(() => null);

          importedObjects.push({
            sourceKey: key,
            gcsObjectName,
            bytes: payloadBuffer.length,
          });
        } catch (itemErr) {
          errors.push({ key, error: itemErr.message });
        }
      }

      recordFlightEvent(projectId, {
        actionType: 'STORAGE_S3_COMPATIBLE_IMPORT',
        title: `Imported ${importedObjects.length} object(s) from ${providerType} (${
          remoteBucket || sandboxProfile.bucket
        }) into gs://${bucketName}`,
        targetName: bucketName,
        region: 'GLOBAL',
        undoable: false,
      });

      return res.json({
        ok: true,
        providerType,
        destinationBucket: bucketName,
        importedCount: importedObjects.length,
        importedObjects,
        errors,
        message: `Imported ${importedObjects.length} object(s) from ${providerType} into gs://${bucketName}!`,
      });
    } catch (err) {
      return res.status(500).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          'Failed to import S3/MinIO/Ceph objects into Google Cloud Storage.',
      });
    }
  }
);

// 3) Create or Generate Google Cloud Storage Transfer Service Job (awsS3Data / awsS3CompatibleData for MinIO & Ceph)
app.post(
  '/api/project/:id/storage/buckets/:bucketName/s3-compatible/transfer-job',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    const {
      providerType = 'MINIO',
      endpoint = 'https://s3.us-east-1.amazonaws.com',
      region = 'us-east-1',
      remoteBucket = 'my-source-bucket',
      prefix = '',
      targetPrefix = '',
      accessKeyId = '',
      secretAccessKey = '',
      pathStyle = true,
    } = req.body || {};

    const cleanHost = String(endpoint || 's3.us-east-1.amazonaws.com')
      .replace(/^https?:\/\//i, '')
      .replace(/\/+$/, '');
    const isHttps = !/^http:\/\//i.test(String(endpoint || ''));

    const transferSpec =
      providerType === 'AWS_S3'
        ? {
            awsS3DataSource: {
              bucketName: remoteBucket,
              ...(prefix ? { path: prefix } : {}),
              ...(accessKeyId && secretAccessKey
                ? {
                    awsAccessKey: {
                      accessKeyId,
                      secretAccessKey,
                    },
                  }
                : {}),
            },
            gcsDataSink: {
              bucketName,
              ...(targetPrefix ? { path: targetPrefix } : {}),
            },
          }
        : {
            awsS3CompatibleDataSource: {
              bucketName: remoteBucket,
              endpoint: cleanHost,
              ...(prefix ? { path: prefix } : {}),
              region: region || 'us-east-1',
              s3Metadata: {
                authMethod: 'AUTH_METHOD_AWS_SIGNATURE_V4',
                requestModel: pathStyle
                  ? 'REQUEST_MODEL_PATH_STYLE'
                  : 'REQUEST_MODEL_VIRTUAL_HOSTED_STYLE',
                protocol: isHttps
                  ? 'NETWORK_PROTOCOL_HTTPS'
                  : 'NETWORK_PROTOCOL_HTTP',
                listApi: 'LIST_OBJECTS_V2',
              },
            },
            gcsDataSink: {
              bucketName,
              ...(targetPrefix ? { path: targetPrefix } : {}),
            },
          };

    const gcloudCli =
      providerType === 'AWS_S3'
        ? `gcloud transfer jobs create s3://${remoteBucket}/${prefix} gs://${bucketName}/${targetPrefix} --project=${projectId} --source-creds-file=aws-creds.txt`
        : `gcloud transfer jobs create s3://${remoteBucket}/${prefix} gs://${bucketName}/${targetPrefix} --project=${projectId} --source-endpoint=${cleanHost} --source-signing-region=${
            region || 'us-east-1'
          } --source-auth-method=AWS_SIGNATURE_V4 --source-request-model=${
            pathStyle ? 'PATH_STYLE' : 'VIRTUAL_HOSTED_STYLE'
          }`;

    const rcloneCli = `rclone sync :s3:${remoteBucket}/${prefix} :gcs:${bucketName}/${targetPrefix} --s3-provider=${
      providerType === 'MINIO'
        ? 'Minio'
        : providerType === 'CEPH_RGW'
        ? 'Ceph'
        : 'AWS'
    } --s3-endpoint=${endpoint} --s3-region=${region || 'us-east-1'}`;

    return res.json({
      ok: true,
      providerType,
      transferJobPayload: {
        projectId,
        description: `CloudPulse ${providerType} (${remoteBucket}) -> gs://${bucketName} Federation Sync`,
        status: 'ENABLED',
        transferSpec,
      },
      gcloudCli,
      rcloneCli,
      message: `Generated Google Cloud Storage Transfer Service spec (${
        providerType === 'AWS_S3' ? 'awsS3DataSource' : 'awsS3CompatibleDataSource'
      }) for gs://${bucketName}!`,
    });
  }
);

// 6c. Toggle Object Public Access & Generate Live Public HTTPS URI (https://storage.googleapis.com/...)
app.post(
  '/api/project/:id/storage/buckets/:bucketName/objects/public-access',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    const {
      objectName,
      makePublic = true,
      preferredScope = 'AUTO', // 'AUTO' | 'OBJECT_ACL' | 'BUCKET_IAM'
    } = req.body || {};

    if (!objectName) {
      return res.status(400).json({ error: 'Missing objectName.' });
    }

    const encodedObjectPath = String(objectName)
      .split('/')
      .map((seg) => encodeURIComponent(seg))
      .join('/');
    const publicHttpsUrl = `https://storage.googleapis.com/${encodeURIComponent(
      bucketName
    )}/${encodedObjectPath}`;
    const authenticatedHttpsUrl = `https://storage.cloud.google.com/${encodeURIComponent(
      bucketName
    )}/${encodedObjectPath}`;
    const gsUri = `gs://${bucketName}/${objectName}`;

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) {
        return res
          .status(401)
          .json({ error: 'Not authenticated with Google Cloud.' });
      }

      const headers = {
        Authorization: `Bearer ${token}`,
        'x-goog-user-project': projectId,
      };

      if (makePublic) {
        // Step 1: Inspect bucket iamConfiguration so we can relax PAP ('inherited') if needed
        const bucketRes = await gcpHttp.get(
          `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
            bucketName
          )}`,
          { headers, timeout: 6000 }
        );
        const iamConfig = bucketRes.data?.iamConfiguration || {};
        const papEnforced =
          iamConfig.publicAccessPrevention === 'enforced';
        const ublaEnabled = Boolean(
          iamConfig.uniformBucketLevelAccess?.enabled
        );

        // Relax Public Access Prevention to 'inherited' so GCP allows allUsers access
        if (papEnforced) {
          await gcpHttp.patch(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}`,
            {
              iamConfiguration: {
                publicAccessPrevention: 'inherited',
              },
            },
            { headers, timeout: 7000 }
          );
        }

        let appliedScope = 'BUCKET_IAM';

        // Try Single-Object Fine-Grained ACL first if UBLA is disabled or user requested OBJECT_ACL
        if (!ublaEnabled || preferredScope === 'OBJECT_ACL') {
          try {
            if (ublaEnabled && preferredScope === 'OBJECT_ACL') {
              await gcpHttp.patch(
                `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
                  bucketName
                )}`,
                {
                  iamConfiguration: {
                    publicAccessPrevention: 'inherited',
                    uniformBucketLevelAccess: { enabled: false },
                  },
                },
                { headers, timeout: 7000 }
              );
            }

            await gcpHttp.post(
              `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
                bucketName
              )}/o/${encodeURIComponent(objectName)}/acl`,
              {
                entity: 'allUsers',
                role: 'READER',
              },
              { headers, timeout: 7000 }
            );
            appliedScope = 'OBJECT_ACL';
          } catch {
            appliedScope = 'BUCKET_IAM';
          }
        }

        // If Uniform Bucket-Level Access (UBLA) is active or fallback needed, bind allUsers -> roles/storage.objectViewer
        if (appliedScope === 'BUCKET_IAM') {
          const iamGet = await gcpHttp.get(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/iam`,
            { headers, timeout: 6000 }
          );
          const policy = iamGet.data || { bindings: [] };
          const bindings = Array.isArray(policy.bindings)
            ? [...policy.bindings]
            : [];
          const viewerRole = 'roles/storage.objectViewer';
          const existingBinding = bindings.find((b) => b.role === viewerRole && !b.condition);
          if (existingBinding) {
            if (!existingBinding.members.includes('allUsers')) {
              existingBinding.members.push('allUsers');
            }
          } else {
            bindings.push({
              role: viewerRole,
              members: ['allUsers'],
            });
          }

          await gcpHttp.put(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/iam`,
            {
              ...policy,
              bindings,
            },
            { headers, timeout: 7000 }
          );
        }

        recordFlightEvent(projectId, {
          actionType: 'STORAGE_OBJECT_PUBLIC_ENABLE',
          title: `Enabled Public HTTPS URI for gs://${bucketName}/${objectName} (${appliedScope})`,
          targetName: `${bucketName}/${objectName}`,
          region: 'GLOBAL',
          undoable: false,
        });

        return res.json({
          ok: true,
          isPublic: true,
          publicAccessScope: appliedScope,
          publicHttpsUrl,
          authenticatedHttpsUrl,
          gsUri,
          message: `Object is now Public! Live HTTPS URI: ${publicHttpsUrl}`,
        });
      } else {
        // Make Private: Revoke object ACL (if Fine-Grained) + remove allUsers from Bucket IAM
        await gcpHttp
          .delete(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/o/${encodeURIComponent(objectName)}/acl/allUsers`,
            { headers, timeout: 5000 }
          )
          .catch(() => null);

        try {
          const iamGet = await gcpHttp.get(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/iam`,
            { headers, timeout: 6000 }
          );
          const policy = iamGet.data || { bindings: [] };
          const cleanedBindings = (policy.bindings || [])
            .map((b) => ({
              ...b,
              members: (b.members || []).filter(
                (m) => m !== 'allUsers' && m !== 'allAuthenticatedUsers'
              ),
            }))
            .filter((b) => b.members.length > 0);

          await gcpHttp.put(
            `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
              bucketName
            )}/iam`,
            {
              ...policy,
              bindings: cleanedBindings,
            },
            { headers, timeout: 7000 }
          );
        } catch {
          // ignore IAM cleanup error if only object ACL was used
        }

        return res.json({
          ok: true,
          isPublic: false,
          publicAccessScope: 'PRIVATE',
          publicHttpsUrl,
          authenticatedHttpsUrl,
          gsUri,
          message: `Revoked public access on gs://${bucketName}/${objectName} (Private Zero-Trust restored).`,
        });
      }
    } catch (err) {
      return res.status(500).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to toggle public access on gs://${bucketName}/${objectName}`,
      });
    }
  }
);

// 7. Delete a Specific Object from a Bucket
app.delete(
  '/api/project/:id/storage/buckets/:bucketName/objects',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    const objectName =
      req.query.name || req.query.objectName || req.body?.objectName;
    const generation = req.query.generation || req.body?.generation;
    if (!objectName) {
      return res.status(400).json({ error: 'Missing object name to delete.' });
    }
    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) {
        return res.status(401).json({ error: 'Not authenticated with Google Cloud.' });
      }

      markArtifactDeleting(`${bucketName}/${objectName}`);

      const url = `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
        bucketName
      )}/o/${encodeURIComponent(objectName)}${
        generation ? `?generation=${encodeURIComponent(generation)}` : ''
      }`;

      await gcpHttp.delete(url, {
        headers: {
          Authorization: `Bearer ${token}`,
          'x-goog-user-project': projectId,
        },
        timeout: 6000,
      });

      res.json({
        ok: true,
        message: `Deleted gs://${bucketName}/${objectName}`,
      });
    } catch (err) {
      res.status(500).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to delete gs://${bucketName}/${objectName}`,
      });
    }
  }
);

// 8. 1-Tap Empty All Objects/Versions & Delete Bucket (Solves 409 BucketNotEmpty)
app.post(
  '/api/project/:id/storage/buckets/:bucketName/empty-and-delete',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) {
        return res.status(401).json({ error: 'Not authenticated with Google Cloud.' });
      }

      markArtifactDeleting(`bucket:${bucketName}`);

      // List all object versions
      const listRes = await gcpHttp.get(
        `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
          bucketName
        )}/o?versions=true&maxResults=500`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            'x-goog-user-project': projectId,
          },
          timeout: 8000,
        }
      );

      const items = listRes.data?.items || [];
      let purgedCount = 0;

      // Delete objects in parallel batches of 15
      for (let i = 0; i < items.length; i += 15) {
        const batch = items.slice(i, i + 15);
        await Promise.allSettled(
          batch.map((obj) => {
            markArtifactDeleting(`${bucketName}/${obj.name}`);
            return gcpHttp
              .delete(
                `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
                  bucketName
                )}/o/${encodeURIComponent(obj.name)}${
                  obj.generation
                    ? `?generation=${encodeURIComponent(obj.generation)}`
                    : ''
                }`,
                {
                  headers: {
                    Authorization: `Bearer ${token}`,
                    'x-goog-user-project': projectId,
                  },
                  timeout: 5000,
                }
              )
              .then(() => {
                purgedCount += 1;
              });
          })
        );
      }

      // Delete the bucket itself
      await gcpHttp.delete(
        `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
          bucketName
        )}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            'x-goog-user-project': projectId,
          },
          timeout: 8000,
        }
      );

      recordFlightEvent(projectId, {
        actionType: 'STORAGE_BUCKET_FORCE_DELETE',
        title: `Emptied (${purgedCount} objects) & deleted bucket gs://${bucketName}`,
        targetName: bucketName,
        region: 'GLOBAL',
        undoable: false,
      });

      res.json({
        ok: true,
        purgedCount,
        message: `Purged ${purgedCount} object(s) and deleted bucket gs://${bucketName}!`,
      });
    } catch (err) {
      res.status(500).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to empty and delete gs://${bucketName}`,
      });
    }
  }
);

// 9. 1-Tap Cross-Region Bucket Teleporter & Object Replicator
app.post(
  '/api/project/:id/storage/buckets/:bucketName/teleport',
  async (req, res) => {
    const { id: projectId, bucketName } = req.params;
    const {
      targetLocation = 'us-central1',
      targetStorageClass = 'STANDARD',
      newBucketName = '',
      copyObjects = true,
    } = req.body || {};

    const cleanTargetBucket = (
      newBucketName ||
      `${bucketName}-${targetLocation.toLowerCase().replace(/[^a-z0-9-]/g, '')}`
    )
      .toLowerCase()
      .replace(/[^a-z0-9-_]/g, '-')
      .slice(0, 62);

    try {
      const { token } = await resolveRequestAuth(req);
      if (!token) {
        return res.status(401).json({ error: 'Not authenticated with Google Cloud.' });
      }

      // 1. Create the destination bucket in targetLocation with Zero-Trust defaults
      const createRes = await gcpHttp.post(
        `https://storage.googleapis.com/storage/v1/b?project=${encodeURIComponent(
          projectId
        )}`,
        {
          name: cleanTargetBucket,
          location: targetLocation.toUpperCase(),
          storageClass: targetStorageClass,
          iamConfiguration: {
            uniformBucketLevelAccess: { enabled: true },
            publicAccessPrevention: 'enforced',
          },
          versioning: { enabled: true },
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            'x-goog-user-project': projectId,
          },
          timeout: 10000,
        }
      );

      let copiedObjectsCount = 0;
      if (copyObjects) {
        const listRes = await gcpHttp.get(
          `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
            bucketName
          )}/o?maxResults=100`,
          {
            headers: {
              Authorization: `Bearer ${token}`,
              'x-goog-user-project': projectId,
            },
            timeout: 6000,
          }
        );
        const objs = listRes.data?.items || [];
        await Promise.allSettled(
          objs.map((o) =>
            gcpHttp
              .post(
                `https://storage.googleapis.com/storage/v1/b/${encodeURIComponent(
                  bucketName
                )}/o/${encodeURIComponent(
                  o.name
                )}/rewriteTo/b/${encodeURIComponent(
                  cleanTargetBucket
                )}/o/${encodeURIComponent(o.name)}`,
                { storageClass: targetStorageClass },
                {
                  headers: {
                    Authorization: `Bearer ${token}`,
                    'x-goog-user-project': projectId,
                  },
                  timeout: 8000,
                }
              )
              .then(() => {
                copiedObjectsCount += 1;
              })
          )
        );
      }

      recordFlightEvent(projectId, {
        actionType: 'STORAGE_BUCKET_TELEPORT',
        title: `Teleported bucket gs://${bucketName} -> gs://${cleanTargetBucket} (${targetLocation}, ${copiedObjectsCount} objects cloned)`,
        targetName: cleanTargetBucket,
        region: targetLocation,
        undoable: true,
        undoPayload: {
          resourceType: 'Cloud Storage Bucket',
          name: cleanTargetBucket,
          region: targetLocation,
        },
      });

      res.json({
        ok: true,
        bucket: createRes.data,
        newBucketName: cleanTargetBucket,
        targetLocation,
        copiedObjectsCount,
        message: `Teleported gs://${bucketName} → gs://${cleanTargetBucket} in ${targetLocation} (${copiedObjectsCount} object(s) replicated with Zero-Trust PAP & UBLA)!`,
      });
    } catch (err) {
      res.status(500).json({
        error:
          err.response?.data?.error?.message ||
          err.message ||
          `Failed to teleport bucket gs://${bucketName}`,
      });
    }
  }
);

