const socEd25519KeyPair = crypto.generateKeyPairSync('ed25519');
const socPublicKeyPem = socEd25519KeyPair.publicKey
  .export({ type: 'spki', format: 'pem' })
  .toString();
const socForensicReceiptsByProject = new Map();
const socIamCheckpointsByProject = new Map();

function captureSocIamCheckpoint(projectId, iamPolicyObj, label = 'Baseline Auto-Snapshot', actor = 'soc-autopilot') {
  const bindings = Array.isArray(iamPolicyObj?.bindings)
    ? JSON.parse(JSON.stringify(iamPolicyObj.bindings))
    : [];
  const etag = iamPolicyObj?.etag || '';
  const canonical = JSON.stringify({ projectId, etag, bindings });
  const policySha256 = crypto.createHash('sha256').update(canonical).digest('hex');
  const signatureHex = crypto
    .sign(null, Buffer.from(canonical, 'utf8'), socEd25519KeyPair.privateKey)
    .toString('hex');

  const list = socIamCheckpointsByProject.get(projectId) || [];
  const isAutoSnapshot =
    label === 'Baseline Auto-Snapshot' ||
    label === 'Auto-Captured Live IAM Policy Snapshot';
  // For automatic background polls, only seed the initial baseline checkpoint if none exists yet
  if (list.length > 0 && isAutoSnapshot) {
    return list[0];
  }
  const ckptId = `iam-ckpt-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
  const nowIso = new Date().toISOString();
  const totalMembersCount = bindings.reduce(
    (acc, b) => acc + (b.members?.length || 0),
    0
  );
  const ckpt = {
    id: ckptId,
    checkpointId: ckptId,
    timestamp: nowIso,
    capturedAt: nowIso,
    label,
    actor,
    etag,
    bindingsCount: bindings.length,
    totalMembersCount,
    membersCount: totalMembersCount,
    policySha256,
    sha256: policySha256,
    signatureHex,
    ed25519Signature: signatureHex,
    bindings,
  };
  list.unshift(ckpt);
  socIamCheckpointsByProject.set(projectId, list.slice(0, 20));
  return ckpt;
}

function appendSocForensicReceipt(projectId, receipt) {
  const list = socForensicReceiptsByProject.get(projectId) || [];
  const prevHash = list[0]?.receiptHash || '0'.repeat(64);
  const canonicalPayload = JSON.stringify({
    projectId,
    prevHash,
    timestamp: receipt.timestamp,
    action: receipt.action,
    target: receipt.target,
    actor: receipt.actor,
    details: receipt.details,
  });
  const receiptHash = crypto
    .createHash('sha256')
    .update(canonicalPayload)
    .digest('hex');
  const signatureHex = crypto
    .sign(null, Buffer.from(canonicalPayload, 'utf8'), socEd25519KeyPair.privateKey)
    .toString('hex');
  const fullReceipt = {
    id: `soc-rcpt-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
    ...receipt,
    prevHash,
    receiptHash,
    signatureHex,
    verifiedEd25519: true,
  };
  list.unshift(fullReceipt);
  socForensicReceiptsByProject.set(projectId, list.slice(0, 50));
  return fullReceipt;
}

